func (rs *ResolutionService) Start(ctx context.Context, numWorkers int) {
	if numWorkers < 1 {
		numWorkers = 2
	}
	for i := 0; i < numWorkers; i++ {
		rs.workerWg.Add(1)
		go rs.worker(ctx, i)
	}
	log.Printf("[resolution-service] started %d workers", numWorkers)
}
```

### `ResolutionService.Stop` (lines 123-134)
