func (rs *ResolutionService) Stop() {
	close(rs.stopChan)
	rs.workerWg.Wait()

	rs.poolsMu.Lock()
	defer rs.poolsMu.Unlock()
	for _, pool := range rs.pools {
		pool.CloseAll()
	}
	rs.pools = make(map[string]*WazeroPool)
	log.Println("[resolution-service] stopped")
}
```

